package com.dlxyuki.wms.pickingbol;
import static org.assertj.core.api.Assertions.assertThat;import java.nio.charset.StandardCharsets;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.web.bind.annotation.GetMapping;
class BolPdfReadContractTest{@Test void routeAndPdfContract()throws Exception{assertThat(BolController.class.getDeclaredMethod("pdf",long.class,com.dlxyuki.wms.user.UserAccount.class).getAnnotation(GetMapping.class).value()).containsExactly("/{bolId}/pdf");Map<String,Object>b=new LinkedHashMap<>();b.put("bol_no","BOL(1)");b.put("ship_from_name","DLX");b.put("ship_from_address","Los Angeles");b.put("ship_to_name",null);b.put("ship_to_address",null);Map<String,Object>i=new LinkedHashMap<>();i.put("ob_no","OB1");i.put("container_number","CONT1");i.put("pallet_qty","12.50");i.put("carton_qty","20");i.put("weight_lbs","100.25");i.put("cbm","2.5");String pdf=new String(PickingBolService.bolPdf(b,List.of(i)),StandardCharsets.UTF_8);assertThat(pdf).startsWith("%PDF-1.4").contains("BOL No: BOL\\(1\\)","Outbound: OB1","12.50 PLT","%%EOF");}}
